#!/usr/bin/env python3
import r2pipe
import json

def analyze_binary():
    r2 = r2pipe.open('/home/ctfplayer/ctf_files/attachment/vm')
    r2.cmd('aaa')  # Analyze all

    # Get thread functions
    thread_funcs = [
        'fcn.00101509',  # Thread 1-10
        'fcn.00101c21',  # Thread 11
        'fcn.00101edf',  # Thread 12
        'fcn.00101f71'   # Thread 13
    ]

    print("=== Thread Function Analysis ===")
    for func in thread_funcs:
        print(f"\nAnalyzing {func}:")
        # Get function details
        func_info = r2.cmdj(f'pdfj @ {func}')
        if func_info:
            # Look for comparison instructions
            for instr in func_info['ops']:
                if any(x in instr.get('opcode', '') for x in ['cmp', 'test', 'je', 'jne', 'jz', 'jnz']):
                    print(f"Compare at {hex(instr['offset'])}: {instr['opcode']}")

            # Look for memory writes
            for instr in func_info['ops']:
                if any(x in instr.get('opcode', '') for x in ['mov', 'lea']):
                    if '[' in instr.get('opcode', ''):
                        print(f"Memory access at {hex(instr['offset'])}: {instr['opcode']}")

    r2.quit()

if __name__ == '__main__':
    analyze_binary()

