import r2pipe
import json

def analyze_binary():
    r2 = r2pipe.open('/home/ctfplayer/ctf_files/attachment/vm')
    r2.cmd('aaa')  # Analyze all

    # Get thread functions
    thread_funcs = r2.cmdj('afl')  # List all functions

    # Look for thread related functions
    for func in thread_funcs:
        if 'thread' in func['name'].lower():
            print(f"Found thread function: {func['name']} at {hex(func['offset'])}")

            # Get cross references
            xrefs = r2.cmdj(f'axtj @ {func["name"]}')
            if xrefs:
                print("Cross references:")
                for xref in xrefs:
                    print(f"  Called from {hex(xref['from'])}")

            # Get function disassembly
            disasm = r2.cmdj(f'pdfj @ {func["name"]}')
            if disasm:
                print("Important instructions:")
                for instr in disasm.get('ops', []):
                    if any(x in instr.get('disasm', '').lower() for x in ['cmp', 'test', 'je', 'jne']):
                        print(f"  {hex(instr['offset'])}: {instr['disasm']}")

            print()

    r2.quit()

if __name__ == '__main__':
    analyze_binary()

